-- VTID-05023 parts 8b + 12(i) rollback — run on SUPABASE only, after the Aurora->Supabase DMS CDC
-- tasks are STOPPED and before traffic returns to Supabase; then run
-- supabase-cutover-unschedule-rollback.sql. Restores every public user trigger to the state
-- snapshotted by supabase-cutover-reverse-cdc-triggers.sql (O = enabled, D = disabled,
-- R = replica, A = always). One statement per line. Idempotent.
DO $chk$ BEGIN IF to_regclass('vtid_05023_backup.trigger_state_snapshot') IS NULL THEN RAISE EXCEPTION 'VTID-05023: no trigger snapshot — nothing to restore from, stop'; END IF; IF NOT EXISTS (SELECT 1 FROM vtid_05023_backup.trigger_state_snapshot) THEN RAISE EXCEPTION 'VTID-05023: no trigger snapshot — nothing to restore from, stop'; END IF; END $chk$;
DO $res$ DECLARE r record; BEGIN FOR r IN SELECT s.table_name, s.trigger_name, s.tgenabled FROM vtid_05023_backup.trigger_state_snapshot s JOIN pg_class c ON c.relname = s.table_name AND c.relnamespace = 'public'::regnamespace JOIN pg_trigger t ON t.tgrelid = c.oid AND t.tgname = s.trigger_name WHERE t.tgenabled <> s.tgenabled ORDER BY 1, 2 LOOP EXECUTE format('ALTER TABLE public.%I %s TRIGGER %I', r.table_name, CASE r.tgenabled WHEN 'O' THEN 'ENABLE' WHEN 'D' THEN 'DISABLE' WHEN 'R' THEN 'ENABLE REPLICA' WHEN 'A' THEN 'ENABLE ALWAYS' END, r.trigger_name); END LOOP; END $res$;
DO $ver$ DECLARE n integer; BEGIN SELECT count(*) INTO n FROM vtid_05023_backup.trigger_state_snapshot s JOIN pg_class c ON c.relname = s.table_name AND c.relnamespace = 'public'::regnamespace JOIN pg_trigger t ON t.tgrelid = c.oid AND t.tgname = s.trigger_name WHERE t.tgenabled <> s.tgenabled; IF n > 0 THEN RAISE EXCEPTION 'VTID-05023: % triggers differ from the snapshot after restore', n; END IF; RAISE NOTICE 'VTID-05023: public user triggers restored to the snapshot'; END $ver$;
